import Foundation
import CoreLocation

// MARK: - DistrictBoundary

public struct DistrictBoundary: Identifiable, Sendable {
    public var id: String { "\(stateCode)_\(name)" }
    public let name: String
    public let stateCode: String
    public let centerLatitude: Double
    public let centerLongitude: Double
    public let rawCoordinates: [(Double, Double)]

    public var centerCoordinate: CLLocationCoordinate2D {
        CLLocationCoordinate2D(latitude: centerLatitude, longitude: centerLongitude)
    }

    public var coordinates: [CLLocationCoordinate2D] {
        rawCoordinates.map { CLLocationCoordinate2D(latitude: $0.0, longitude: $0.1) }
    }
}

// MARK: - IndianDistrictBoundaryData

enum IndianDistrictBoundaryData {

    /// Returns all district boundaries for the given state code.
    static func districts(for stateCode: String) -> [DistrictBoundary] {
        return districtRegistry[stateCode.uppercased()] ?? []
    }

